#!/bin/sh
# `--print-shell` integration tests: the snippets must be generated by the
# launcher itself, not read from a `shell/` directory beside it. Every
# documented install copies bin/prompt-nvim onto PATH on its own, so a
# repo-relative lookup silently broke the shell integration for every user who
# did not run straight from a checkout.
#
# Run directly: tests/integration/print_shell_spec.sh
# Exit code: 0 if every test passed, 1 otherwise. Emits TAP-ish "ok"/"not ok"
# lines plus a final "N passed, M failed" summary, same shape as tests/run.lua.
set -u

script_dir=$(CDPATH='' cd -- "$(dirname -- "$0")" && pwd)
root_dir=$(CDPATH='' cd -- "$script_dir/../.." && pwd)
launcher="$root_dir/bin/prompt-nvim"

# Every target the wrappers are expected to cover, mirroring SHELL_TARGETS in
# the launcher. Hard-coded rather than sourced so a typo there fails the test.
targets="claude codex gemini opencode pi"

pass_count=0
fail_count=0

pass() {
    pass_count=$((pass_count + 1))
    printf 'ok - %s\n' "$1"
}

fail() {
    fail_count=$((fail_count + 1))
    printf 'not ok - %s: %s\n' "$1" "$2"
}

work_dir=$(mktemp -d)
# shellcheck disable=SC2329 # invoked indirectly via `trap ... EXIT INT TERM`
cleanup() {
    rm -rf -- "$work_dir"
}
trap cleanup EXIT INT TERM

# A launcher copied somewhere with no `shell/` directory anywhere above it —
# the shape produced by the README's vim.pack/lazy.nvim/manual install steps.
installed_dir="$work_dir/opt/bin"
mkdir -p "$installed_dir"
cp -- "$launcher" "$installed_dir/prompt-nvim"
chmod +x "$installed_dir/prompt-nvim"
installed="$installed_dir/prompt-nvim"

# emits_all_targets NAME LAUNCHER SHELL DEF_TEMPLATE ASSIGN_TEMPLATE
# Both templates use @ as the placeholder for the target name: DEF_TEMPLATE is
# the wrapper's definition line, ASSIGN_TEMPLATE its PROMPT_NVIM_TARGET
# assignment (spelled differently per shell).
emits_all_targets() {
    _name="$1"
    _launcher="$2"
    _shell="$3"
    _def="$4"
    _assign="$5"

    _out="$work_dir/out-$_shell.txt"
    if ! sh "$_launcher" --print-shell "$_shell" >"$_out" 2>"$work_dir/err.txt"; then
        fail "$_name" "exited $? : $(cat "$work_dir/err.txt")"
        return
    fi

    _missing=""
    for _t in $targets; do
        _pattern=$(printf '%s\n' "$_def" | sed "s/@/$_t/g")
        grep -qF -- "$_pattern" "$_out" || _missing="$_missing $_t"
    done
    if [ -n "$_missing" ]; then
        fail "$_name" "no wrapper emitted for:$_missing"
        return
    fi

    # A wrapper that forgets the target leaves the plugin with no way to
    # resolve one, which silently disables every completion trigger.
    for _t in $targets; do
        _pattern=$(printf '%s\n' "$_assign" | sed "s/@/$_t/g")
        grep -qF -- "$_pattern" "$_out" || _missing="$_missing $_t"
    done
    if [ -n "$_missing" ]; then
        fail "$_name" "no PROMPT_NVIM_TARGET assignment for:$_missing"
        return
    fi

    pass "$_name"
}

test_posix_shells_from_checkout() {
    emits_all_targets "bash snippet defines every wrapper" \
        "$launcher" bash '@() {' 'PROMPT_NVIM_TARGET=@'
    emits_all_targets "zsh snippet defines every wrapper" \
        "$launcher" zsh '@() {' 'PROMPT_NVIM_TARGET=@'
}

test_fish_and_nushell_from_checkout() {
    emits_all_targets "fish snippet defines every wrapper" \
        "$launcher" fish 'function @' 'PROMPT_NVIM_TARGET=@'
    emits_all_targets "nushell snippet defines every wrapper" \
        "$launcher" nu 'def --wrapped @ [...args]' 'PROMPT_NVIM_TARGET: @'
}

# The regression: same output from a launcher installed on its own.
test_installed_copy_matches_checkout() {
    for _shell in bash zsh fish nu; do
        _from_repo="$work_dir/repo-$_shell.txt"
        _from_copy="$work_dir/copy-$_shell.txt"
        sh "$launcher" --print-shell "$_shell" >"$_from_repo" 2>/dev/null
        _repo_status=$?
        sh "$installed" --print-shell "$_shell" >"$_from_copy" 2>/dev/null
        _copy_status=$?

        if [ "$_repo_status" -ne 0 ] || [ "$_copy_status" -ne 0 ]; then
            fail "copied launcher prints $_shell integration" \
                "repo_status=$_repo_status copy_status=$_copy_status"
        elif ! cmp -s -- "$_from_repo" "$_from_copy"; then
            fail "copied launcher prints $_shell integration" "output differs from the checkout"
        else
            pass "copied launcher prints $_shell integration"
        fi
    done
}

# The emitted bash/zsh snippet has to be syntactically valid, or `eval` in a
# shell rc breaks the user's whole session rather than just the integration.
test_posix_snippet_parses() {
    sh "$installed" --print-shell bash >"$work_dir/parse.sh" 2>/dev/null
    if sh -n "$work_dir/parse.sh" 2>"$work_dir/parse-err.txt"; then
        pass "emitted bash/zsh snippet parses under sh -n"
    else
        fail "emitted bash/zsh snippet parses under sh -n" "$(cat "$work_dir/parse-err.txt")"
    fi
}

test_nushell_alias_accepted() {
    if sh "$installed" --print-shell nushell >/dev/null 2>&1; then
        pass "nushell is accepted as an alias for nu"
    else
        fail "nushell is accepted as an alias for nu" "exited nonzero"
    fi
}

test_unknown_shell_is_rejected() {
    sh "$installed" --print-shell bogus >"$work_dir/bogus.txt" 2>"$work_dir/bogus-err.txt"
    status=$?
    if [ "$status" -eq 2 ] && [ ! -s "$work_dir/bogus.txt" ] &&
        grep -q 'unknown shell' "$work_dir/bogus-err.txt"; then
        pass "unknown shell exits 2 with an error on stderr and no stdout"
    else
        fail "unknown shell exits 2 with an error on stderr and no stdout" \
            "status=$status stdout=$(cat "$work_dir/bogus.txt")"
    fi
}

test_posix_shells_from_checkout
test_fish_and_nushell_from_checkout
test_installed_copy_matches_checkout
test_posix_snippet_parses
test_nushell_alias_accepted
test_unknown_shell_is_rejected

printf '%s passed, %s failed\n' "$pass_count" "$fail_count"

if [ "$fail_count" -gt 0 ]; then
    exit 1
fi
exit 0
